import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Color, DoubleSide, DataTexture, RGBAFormat } from 'three/webgpu';
import { uv, uniform, mix, smoothstep, texture, vec3, float, Fn, vec2, abs, sub, max, min, sqrt, mul, add, negate } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();
  group.name = 'hub-collection-badge';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const colors = config.intent?.visualSpec?.colors ?? {};
  const accent = new THREE.Color(colors.accent ?? '#ff2a38');
  const ink = new THREE.Color(colors.ink ?? '#16161d');
  const paper = new THREE.Color(colors.paper ?? '#e8ecf2');
  const surface = new THREE.Color(colors.surface ?? '#0b0b10');

  // Dimensions：a small capsule label.
  const W = 0.92, H = 0.36;
  const aspectVal = W / H;
  const geo = new THREE.PlaneGeometry(W, H, 1, 1);

  // Placeholder grain texture (1x1) so material renders synchronously；replaced on load.
  const ph = new Uint8Array([235, 238, 242, 255]);
  const placeholder = new THREE.DataTexture(ph, 1, 1, THREE.RGBAFormat);
  placeholder.needsUpdate = true;

  const grainUniform = uniform(placeholder);

  // TSL rounded-capsule SDF（centered coords, gx in unit half-width=aspect/2）。
  const aspectU = uniform(aspectVal);
  const radiusU = uniform(0.34); // corner radius in centered space
  const edgeU = uniform(0.06);   // accent edge band thickness

  const px = uv.x.sub(0.5).mul(aspectU);
  const py = uv.y.sub(0.5);

  const qx = abs(px).sub(radiusU);
  const qy = abs(py).sub(radiusU);
  const qx2 = max(qx, float(0.0));
  const qy2 = max(qy, float(0.0));
  const inner = min(max(qx, qy), float(0.0));
  const sd = sqrt(add(mul(qx2, qx2), mul(qy2, qy2))).add(inner).sub(radiusU);

  const dpos = negate(sd);             // >0 inside
  const inside = smoothstep(float(0.0), float(0.02), dpos);
  const edge = smoothstep(edgeU, float(0.0), dpos); // 1 at edge, 0 deep inside

  const grainTex = texture(grainUniform, uv);
  const grainLum = grainTex.r;
  // Base：brushed ceramic paper grain, tinted between paper and surface.
  const baseCol = mix(vec3(surface.r, surface.g, surface.b), vec3(paper.r, paper.g, paper.b), grainLum.mul(0.4).add(0.55));
  // Accent edge light.
  const accentCol = vec3(accent.r, accent.g, accent.b);
  const rimCol = mix(accentCol, vec3(1.0, 1.0, 1.0), edge.mul(0.35));
  const col = mix(baseCol, rimCol, edge);
  const alpha = inside.mul(0.96); // slight translucency

  const mat = new MeshBasicNodeMaterial({ side: THREE.DoubleSide, transparent: true });
  mat.colorNode = col;
  mat.alphaNode = alpha;

  const mesh = new THREE.Mesh(geo, mat);
  mesh.renderOrder = 2;
  group.add(mesh);

  // Load real ceramic-grain texture and swap uniform。
  const loaders = [];
  if (config.imageUrl) {
    const p = ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.wrapS = THREE.RepeatWrapping;
      tex.wrapT = THREE.RepeatWrapping;
      tex.anisotropy = 4;
      grainUniform.value = tex;
      mat.needsUpdate = true;
    });
    loaders.push(p);
  }

  // Entrance：weighted-settle rise-in。
  group.position.y = config.scenePosition ? config.scenePosition.y + 0.15 : 1.6 + 0.15;
  group.userData._restY = config.scenePosition ? config.scenePosition.y : 1.6;
  const tl = gsap.timeline({ delay: 0.15, onComplete: () => { group.position.y = group.userData._restY; } });
  tl.to(group.position, { y: group.userData._restY, duration: 0.7, ease: 'power3.out' });
  tl.to(group.scale, { x: 1.04, y: 1.04, duration: 0.5, ease: 'power2.out' }, 0.4);
  tl.to(group.scale, { x: 1.0, y: 1.0, duration: 0.9, ease: 'power4.out' }, 0.9);

  // Interaction handlers。
  let hoverTl = null;
  const handlers = {
    hoverIn() {
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(group.position, { y: group.userData._restY + 0.15, duration: 0.5, ease: 'power2.out' }, 0);
      hoverTl.to(group.scale, { x: 1.05, y: 1.05, duration: 0.4, ease: 'power2.out' }, 0);
      // intensify edge glow。
      gsap.to(edgeU, { value: 0.1, duration: 0.4, ease: 'power2.out', overwrite: true });
    },
    hoverOut() {
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(group.position, { y: group.userData._restY, duration: 0.55, ease: 'power3.out' }, 0);
      hoverTl.to(group.scale, { x: 1.0, y: 1.0, duration: 0.5, ease: 'power3.out' }, 0);
      gsap.to(edgeU, { value: 0.06, duration: 0.5, ease: 'power2.out', overwrite: true });
    },
    click() {
      const pressTl = gsap.timeline();
      pressTl.to(group.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.in(2)' });
      pressTl.to(group.scale, { x: 1.04, y: 1.04, duration: 0.45, ease: 'back.out(2)' });
      gsap.to(accentU_hint(), { /* no-op shake free */ });
      ctx.emit('hub-collection.select', {});
    },
  };

  function accentU_hint() { return { x: 0 }; }

  group.userData.handlers = handlers;

  // Cleanup。
  group.userData.cleanup = () => {
    tl.kill();
    if (hoverTl) hoverTl.kill();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(edgeU);
    geo.dispose();
    mat.dispose();
    placeholder.dispose();
    if (grainUniform.value && grainUniform.value !== placeholder) grainUniform.value.dispose();
  };

  return group;
}
